mapper.select:
        select
        message.*,
        lawyers.name,
        lawyers.avatar,
        users.nick_name,
        users.head_img
        from message message
        left join lawyers lawyers on message.lawyer_id = lawyers.id
		left join users users on message.user_id = users.id

            and message.id = #{id}
            and message.user_id = #{userId}
            and message.lawyer_id = #{lawyerId}
            and message.content = #{content}
            and message.answer = #{answer}
            and message.create_time = #{createTime}
            and message.update_time = #{updateTime}
            and lawyers.name like concat('%',#{name},'%')
            and lawyers.avatar = #{avatar}
            and users.nick_name like concat('%',#{nickName},'%')
            and users.head_img = #{headImg}


            limit #{current},#{pageSize}

        select count(*) from message message
        left join lawyers lawyers on message.lawyer_id = lawyers.id
		left join users users on message.user_id = users.id

            and message.id = #{id}
            and message.user_id = #{userId}
            and message.lawyer_id = #{lawyerId}
            and message.content = #{content}
            and message.answer = #{answer}
            and message.create_time = #{createTime}
            and message.update_time = #{updateTime}
            and lawyers.name like concat('%',#{name},'%')
            and lawyers.avatar = #{avatar}
            and users.nick_name like concat('%',#{nickName},'%')
            and users.head_img = #{headImg}
